SetFunctionName("Set(float, float, float)");
Vector3 v3;
v3.Set(1.1f, 2.2f, 3.4f);
Validate((float)v3.X() == 1.1f && (float)v3.Y() == 2.2f && (float)v3.Z() == 3.4f);



