Vector3 vIn0(2.5f, 1.99f, 1.01f);
Vector3 vIn1(-2.5f, 0.0f, 0.0f);
Vector3 one = Vector3(1.0f, 1.0f, 1.0f);
Vector3 two = float_test_type(2.0f) * one;
Vector3 ref0(2.0f, 1.99f, 1.01f);
Vector3 ref1(1.0f, 1.0f, 1.0f);
Vector3 result0 = Clamp( vIn0, one, two );
Vector3 result1 = Clamp( vIn1, one, two );

SetFunctionName("Clamp(Vector3, Vector3, Vector3");
Validate( result0 == ref0 && result1 == ref1 );



SetFunctionName("Mask3 CompLessThan(Vector3 a, Vector3 b)");
