Vector3 vb(1.0f, 2.0f, 1.0f);

Mask3 mask(CompLessThan(va, vb));
Validate(
    !mask.GetX().GetBool() &&
     mask.GetY().GetBool() &&
    !mask.GetZ().GetBool()
);



