SetFunctionName("Vector3 Select(MaskScalar mask, Vector3 a, Vector3 b)");
Vector3 v1(1.0f, 2.0f, 3.0f);
Vector3 v2(10.0f, 20.0f, 30.0f);

Vector3 result1 = Select( MaskScalar(true), v1, v2 );
Vector3 result2 = Select( MaskScalar(false), v1, v2 );
Validate(
    result1 == v1 &&
    result2 == v2
);


#ifdef HOST_TESTING
        SetFunctionName("Vector3 Select(MaskScalar mask, Vector3 a, Vector3 b)");
        Vector3 v1(1.0f, 2.0f, 3.0f);
        Vector3 v2(-10.0f, -20.0f, -30.0f);
        Vector3 ref1( -1.0f, 20.0f, -3.0f);

        uint32_t values[] = { 0x7fffffff, 0x80000000, 0x7fffffff };
        Mask3 mask(values[0], values[1], values[2]);

        Vector3 result1 = Select( mask, v1, v2 );
