#endif



SetFunctionName("Vector3 Select(Mask3 mask, Vector3 a, Vector3 b)");
Vector3 v1(1.0f, 2.0f, 3.0f);
Vector3 v2(10.0f, 20.0f, 30.0f);
Vector3 ref1(1.0f, 2.0f, 30.0f);
Vector3 ref2(10.0f, 20.0f, 3.0f);
Mask3 mask1(true, true, false);
Mask3 mask2(false, false, true);

Vector3 result1 = Select( mask1, v1, v2 );
Vector3 result2 = Select( mask2, v1, v2 );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector3 Permute<pattern>(value)");
Vector3 v(0.0f, 1.0f, 2.0f);
Vector3 ref1( 2.0f, 0.0f, 1.0f);
Vector3 ref2( 1.0f, 2.0f, 2.0f);
Vector3 result1 = Permute<0x201>(v);
Vector3 result2 = Permute<0x122>(v);
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector3 unaligned load/store tests");
float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = static_cast<float>(i+1);

::rw::math::fpu::Vector3Template<float>* alignedVec = reinterpret_cast< ::rw::math::fpu::Vector3Template<float>*>(&buffer[0]);
Vector3 v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 1.0f && v.Y() == 2.0f && v.Z() == 3.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector3Template<float>*>(&buffer[1]);
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 2.0f && v.Y() == 3.0f && v.Z() == 4.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector3Template<float>*>(&buffer[2]);
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 3.0f && v.Y() == 4.0f && v.Z() == 5.0f);        

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector3Template<float>*>(&buffer[3]);         
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 4.0f && v.Y() == 5.0f && v.Z() == 6.0f);



SetFunctionName("Vector3 unaligned store tests");

float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = 0.0f;

Vector3 v2;

v2.Set(1.1f, 2.2f, 3.3f);
::rw::math::fpu::Vector3* unaligned = reinterpret_cast< ::rw::math::fpu::Vector3*>(&buffer[0]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[0] == 1.1f && buffer[1] == 2.2f && buffer[2] == 3.3f && buffer[3] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector3*>(&buffer[1]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[1] == 1.1f && buffer[2] == 2.2f && buffer[3] == 3.3f && buffer[4] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector3*>(&buffer[2]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[2] == 1.1f && buffer[3] == 2.2f && buffer[4] == 3.3f && buffer[5] == 0);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector3*>(&buffer[3]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[3] == 1.1f && buffer[4] == 2.2f && buffer[5] == 3.3f && buffer[6] == 0);



