Vector3 v3a, output;

float_basic_type fResult;
bool success = true;
SetFunctionName("CheckedNormalizeReturnMagnitude(const Vector3 &v, Vector3 &result)");

v3a.Set(1.0f, 2.0f, 3.45f);
fResult = (float)CheckedNormalizeReturnMagnitude(v3a, output);
success &= IsEqualWithEpsilon(output.X(), (float_basic_type) 0.24323414f);
success &= IsEqualWithEpsilon(output.Y(), (float_basic_type) 0.48646829f);
success &= IsEqualWithEpsilon(output.Z(), (float_basic_type) 0.83915782f);
success &= IsEqualWithEpsilon(fResult, (float_basic_type) 4.1112652f);

v3a.Set(0.0f, 0.0f, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v3a, output);
success &= IsEqualWithEpsilon((float)output.X(), 0.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon((float)output.Z(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_basic_type)0.0f);

v3a.Set(SMALL_FLOAT, 0.0f, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v3a, output);
success &= IsEqualWithEpsilon((float)output.X(), 1.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon((float)output.Z(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_basic_type)0.0f);

v3a.Set(MIN_FLOAT, 0.0f, 0.0f);
fResult = (float)CheckedNormalizeReturnMagnitude(v3a, output);
// Two solutions are acceptable depending on the precision that
// calculations are carried out with.  Either the magnitude appears to
// be zero (e.g. for 32bit calculations), or the magnitude appears to
// be a very small number (i.e. MIN_FLOAT).
// The result vector will then be 0 (if magnitude is zero), or the X
// axis otherwise.
success &= IsEqualWithEpsilon((float)output.X(), 0.0f) || IsEqualWithEpsilon((float)output.X(), 1.0f);
success &= IsEqualWithEpsilon((float)output.Y(), 0.0f);
success &= IsEqualWithEpsilon((float)output.Z(), 0.0f);
success &= IsEqualWithEpsilon(fResult, (float_basic_type)0.0f) || IsEqualWithEpsilon(fResult, (float_basic_type)MIN_FLOAT);

Validate(success);



