#if !defined EA_PLATFORM_PS3_SPU
        SetFunctionName("IsAnyNaN(Vector3 v)");

        float zero = 0.0f;
        float_test_type nan = float_test_type(zero / zero);
        int numPermutations = 1 << Vector3::NumberOfElement;
        bool result = true;
        for( int curPermutation=0;curPermutation<numPermutations;curPermutation++)
        {
            Vector3 vec = Vector3((float_test_type)0.0f, (float_test_type)0.0f, (float_test_type)0.0f);
            for( int elem = 0; elem < Vector3::NumberOfElement; elem++ )
            {
                if( curPermutation & (1<<elem) )
                {
                    vec.SetComponent( elem, nan );
                }
            }
            if( curPermutation == 0 )
            {
                // All bits are zero so the vector has no NaN's
                result &= !IsAnyNaN(vec);
            }
            else
            {
                // At least one element is NaN.
                result &= IsAnyNaN(vec);
            }
        }
        Validate(result);
#endif



