SetFunctionName("Vector3 ClampToNegPosRange(value, range)");
Vector3 range(5.0f,  5.0f, 5.0f);
Vector3   v1( 7.0f,  3.0f, 0.0f);
Vector3   v2(-7.0f, -3.0f, 0.0f);
Vector3 ref1( 5.0f,  3.0f, 0.0f);
Vector3 ref2(-5.0f, -3.0f, 0.0f);
Vector3 result1 = ClampToNegPosRange( v1, range );
Vector3 result2 = ClampToNegPosRange( v2, range );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector3::Vector3(Vector2, scalar)");
Vector2 v2(10.0f, 20.0f);
Vector4 v4(1.0f, 2.0f, 3.0f, 4.0f);

bool result1 = Vector3(v2, 5.0f) == Vector3(10.0f, 20.0f, 5.0f);
bool result2 = Vector3(v2, v4.X()) == Vector3(10.0f, 20.0f, 1.0f);
bool result3 = Vector3(v2, v4.Y()) == Vector3(10.0f, 20.0f, 2.0f);
bool result4 = Vector3(v2, v4.Z()) == Vector3(10.0f, 20.0f, 3.0f);
bool result5 = Vector3(v2, v4.W()) == Vector3(10.0f, 20.0f, 4.0f);
bool result6 = Vector3(v2, v4[1]) == Vector3(10.0f, 20.0f, 2.0f);
Validate(
    result1 && result2 && result3 && result4 && result5 && result6
);



