SetFunctionName("Updating of bounding box - Using Vector Min/Max");

StartTimer(testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE * testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG);

Vector3 bbMin = v3a_array[0];
Vector3 bbMax = v3a_array[0];
for (int testloop = 0; testloop < testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG; testloop++)
{
    for (int i = 0; i < testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE; i++)
    {
        bbMin = Min(v3a_array[i], bbMin );
        bbMax = Max(v3a_array[i], bbMax );
    }
}

// Write values out to memory to make sure the compiler doesn't optimize the loop away.
v3out_array[0] = bbMin;
v3out_array[1] = bbMax;

StopTimer();



SetFunctionName("Updating of bounding box - Using scalar access and branches");

StartTimer(testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE * testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG);

Vector3 bbMin = v3a_array[0];
Vector3 bbMax = v3a_array[0];
for (int testloop = 0; testloop < testing::RW_MATH_UNITTEST_TEST_LOOP_COUNT_LONG; testloop++)
{
    for (int i = 0; i < testing::RW_MATH_UNITTEST_TEST_VECTOR_ARRAY_SIZE; i++)
    {
        if(v3a_array[i].GetX() < bbMin.GetX())		bbMin.SetX(v3a_array[i].GetX());
        if(v3a_array[i].GetY() < bbMin.GetY())		bbMin.SetY(v3a_array[i].GetY());
        if(v3a_array[i].GetZ() < bbMin.GetZ())		bbMin.SetZ(v3a_array[i].GetZ());

        if(v3a_array[i].GetX() > bbMax.GetX())		bbMax.SetX(v3a_array[i].GetX());
        if(v3a_array[i].GetY() > bbMax.GetY())		bbMax.SetY(v3a_array[i].GetY());
        if(v3a_array[i].GetZ() > bbMax.GetZ())		bbMax.SetZ(v3a_array[i].GetZ());
    }
}

// Write values out to memory to make sure the compiler doesn't optimize the loop away.
v3out_array[0] = bbMin;
v3out_array[1] = bbMax;

StopTimer();
